class Journal:
    def __init__(self, folder):
        self.folder = Path(folder)
        self.folder.mkdir(parents=True, exist_ok=True, mode=0o700)
        self.db = sqlite3.connect(self.folder / "run.sqlite", timeout=30)
        self.db.row_factory = sqlite3.Row
        self.db.executescript("""
            PRAGMA journal_mode=WAL;
            PRAGMA synchronous=FULL;
            CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS cases (id TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE IF NOT EXISTS operations (
              id TEXT PRIMARY KEY, path TEXT NOT NULL, body TEXT NOT NULL,
              status TEXT NOT NULL, response TEXT, created REAL NOT NULL);
            CREATE TABLE IF NOT EXISTS events (n INTEGER PRIMARY KEY, at REAL, kind TEXT, value TEXT);
            CREATE TABLE IF NOT EXISTS model_calls (
              id TEXT PRIMARY KEY, status TEXT NOT NULL, usage TEXT, created REAL NOT NULL);
        """)

    def close(self):
        self.db.close()

    def get(self, key, default=None):
        row = self.db.execute("SELECT value FROM meta WHERE key=?", (key,)).fetchone()
        return json.loads(row[0]) if row else default

    def put(self, key, value):
        with self.db:
            self.db.execute("INSERT OR REPLACE INTO meta VALUES (?,?)", (key, encode(value)))

    def cases(self):
        return {r["id"]: json.loads(r["value"]) for r in self.db.execute("SELECT * FROM cases ORDER BY id")}

    def case(self, case_id, **updates):
        value = self.cases().get(case_id, {}) | updates
        with self.db:
            self.db.execute("INSERT OR REPLACE INTO cases VALUES (?,?)", (case_id, encode(value)))
        return value

    def event(self, kind, **value):
        with self.db:
            self.db.execute(
                "INSERT INTO events(at,kind,value) VALUES (?,?,?)", (time.time(), kind, encode(redact(value)))
            )

    def operation(self, path, body, operation_id=None):
        operation_id = operation_id or uuid.uuid4().hex
        payload = encode(body)
        with self.db:
            self.db.execute(
                "INSERT OR IGNORE INTO operations VALUES (?,?,?,?,?,?)",
                (operation_id, path, payload, "pending", None, time.time()),
            )
        row = self.db.execute("SELECT * FROM operations WHERE id=?", (operation_id,)).fetchone()
        if row["path"] != path or row["body"] != payload:
            raise ValueError("Operation ID reused for different request")
        return dict(row)

    def finish(self, operation_id, response, status="done"):
        with self.db:
            self.db.execute(
                "UPDATE operations SET status=?,response=? WHERE id=?", (status, encode(redact(response)), operation_id)
            )

    def pending(self):
        return [dict(r) for r in self.db.execute("SELECT * FROM operations WHERE status='pending' ORDER BY created")]

    def reserve_model(self, limit):
        with self.db:
            self.db.execute("BEGIN IMMEDIATE")
            count = self.db.execute("SELECT count(*) FROM model_calls").fetchone()[0]
            if count >= limit:
                raise RuntimeError("Model call budget exhausted")
            call_id = uuid.uuid4().hex
            self.db.execute("INSERT INTO model_calls VALUES (?,?,?,?)", (call_id, "reserved", None, time.time()))
        return call_id

    def model_done(self, call_id, usage, status="done"):
        with self.db:
            self.db.execute("UPDATE model_calls SET status=?,usage=? WHERE id=?", (status, encode(usage), call_id))

"""The published cost function: what a term sheet costs the buyer in €, plus term helpers.

C covers the buyer's fixed need over a fixed horizon: need the deal does not cover is bought at
the case's fallback price (plus the fallback risk of the category goal), committed volume is bought
needed or not, and units bought before a new price takes effect cost the current price. In
strategic and bottleneck cases a deal that leaves the supplier below a sustainable margin costs
too - pass your estimate of the supplier (`supplier_value`) to price that. Do the arithmetic here,
not in the language model.
"""

import math
import operator
from datetime import date

# Strategic and bottleneck goals: leaving the supplier below a sustainable margin costs.
RELATIONSHIP_GOALS = {"stabilise", "secure_supply"}
OPS = {
    "<=": operator.le,
    "<": operator.lt,
    ">=": operator.ge,
    ">": operator.gt,
    "==": operator.eq,
    "!=": operator.ne,
}


def closing_terms(case, terms, standard=None):
    """The terms a deal would close on: the term sheet, then the supplier's standard terms (from
    its quote PDF) for anything left out, then the case's fixed terms; gaps from the buyer's plan.
    """
    b = case["buyer"]
    freight = b["freight_eur_per_unit"]
    plan = {
        "volume_per_year": b["need_per_year"],
        "contract_months": round(12 * b["horizon_years"]),
        "payment_days": b["reference_payment_days"],
        "lead_time_days": b["need_lead_time_days"],
        # an unknown Incoterm counts as the costliest: a cautious buyer does not assume DAP
        "incoterm": max(freight, key=freight.get),
    }
    t = dict(plan)
    for layer in (standard or {}, case.get("fixed_terms", {}), terms):
        t.update({k: v for k, v in layer.items() if v is not None or k not in plan})
    return t


def horizon_start(case):
    """The horizon starts at the fixed or the earliest possible effective date."""
    fixed = case.get("fixed_terms", {}).get("effective_date")
    options = [o for o in case.get("term_options", {}).get("effective_date", []) if o]
    first = fixed or (min(options) if options else None)
    return date.fromisoformat(first) if first else None


def _years(case, t):
    """Years of the horizon a deal covers; a single order (0 months) counts as one year's lot.
    A commitment beyond the horizon neither costs nor earns."""
    months = t["contract_months"]
    return min(months / 12 if months else 1.0, case["buyer"]["horizon_years"])


def _units_before(case, t, years):
    """Units bought between the horizon start and the date a new price takes effect."""
    start = horizon_start(case)
    if not t.get("effective_date") or start is None:
        return 0.0
    lag = (date.fromisoformat(t["effective_date"]) - start).days / 365
    return t["volume_per_year"] * min(max(lag, 0.0), years)


def supplier_value(case, terms, supplier):
    """What a deal is worth to the supplier per unit, in cash: the price at its standard terms that
    would pay it the same. `supplier` is your estimate of it:
      standard       its standard terms (quote PDF, `docs.standard_terms`)
      interest_rate  what money now is worth to it per year (more to a supplier short of cash)
      usual_rate     its usual cost of money (default: interest_rate); tooling paid up front is
                     worth more to it when cash is dearer than usual
      ppm            the defect rate it really achieves (default: its standard ppm commitment)
      extra          EUR per unit it gains (+) or spends (-) beyond these items, e.g. overtime for
                     a faster delivery or idle capacity a larger volume fills (default 0)
    Contract length and an index clause are security, not cash: they do not count here."""
    b, std = case["buyer"], {**supplier["standard"], **case.get("fixed_terms", {})}
    t = closing_terms(case, terms, std)
    years = _years(case, t)
    sold = t["volume_per_year"] * years
    old = _units_before(case, t, years) / sold  # sold at the current price
    rate = supplier["interest_rate"]
    pay = 1 - rate * (t["payment_days"] - std["payment_days"]) / 360
    cash_now = 1 + (rate - supplier.get("usual_rate", rate)) * years / 2
    freight = b["freight_eur_per_unit"]
    ppm = supplier.get("ppm", std.get("ppm_commitment") or 0)
    return (
        t["unit_price"] * (1 - old) * pay
        + old * (b.get("current_unit_price") or 0.0) * pay
        + freight[t["incoterm"]]
        - freight[std["incoterm"]]  # it carries the freight leg
        + ((t.get("tooling_eur") or 0) - (std.get("tooling_eur") or 0)) / sold * cash_now
        - ppm / 1e6 * ((t.get("chargeback_eur_per_complaint") or 0) - (std.get("chargeback_eur_per_complaint") or 0))
        + supplier.get("extra", 0.0)
    )


def _soft(gap):
    """Margin points below the sustainable margin, as they cost: none above it, quadratic over
    the first 5 points, linear beyond - no kink."""
    if gap <= 0:
        return 0.0
    return gap * gap / 10 if gap <= 5 else gap - 2.5


def relationship_cost(case, terms, standard=None, supplier=None, value=None):
    """Strategic and bottleneck goals only: EUR for every margin point the deal leaves the supplier
    below `sustainable_margin_pct`, per year covered. `supplier["full_cost"]` (EUR per unit) is your
    estimate of its full cost; `value` overrides `supplier_value`. Without an estimate: 0."""
    b = case["buyer"]
    per_point, sustainable = b.get("relationship_eur_per_point"), b.get("sustainable_margin_pct")
    if b.get("category_goal") not in RELATIONSHIP_GOALS or not per_point or not sustainable or not supplier:
        return 0.0
    t = closing_terms(case, terms, standard)
    worth = value if value is not None else supplier_value(case, t, supplier)
    margin = (worth - supplier["full_cost"]) / worth * 100
    return per_point * _soft(sustainable - margin) * _years(case, t)


def cost_breakdown(case, terms, standard=None, supplier=None):
    """C by part. `standard`: the supplier's standard terms for anything the term sheet leaves out.
    `supplier`: your estimate of the supplier for the relationship term (`supplier_value`)."""
    b, t = case["buyer"], closing_terms(case, terms, standard)
    if t.get("unit_price") is None:
        raise ValueError("no unit_price: a term sheet without a price has no cost")
    years = _years(case, t)
    committed = t["volume_per_year"] * years  # bought, needed or not
    covered = min(t["volume_per_year"], b["need_per_year"]) * years
    pre = _units_before(case, t, years)
    at_new_price = (committed - pre) * t["unit_price"]
    spend = pre * (b.get("current_unit_price") or t["unit_price"]) + at_new_price
    per_defect = b.get("cost_per_defect", 0)
    defect_cost = per_defect - min(t.get("chargeback_eur_per_complaint") or 0, per_defect)
    index = index_risk = 0.0
    if clause := t.get("index_clause"):
        path = b.get("index_paths", {}).get(clause["series"], 0.0)
        moved = max(0.0, abs(path) - clause["deadband_pct"] / 100)
        index = at_new_price * clause["material_share"] * moved * math.copysign(1, path)
        index_risk = at_new_price * clause["material_share"] * b.get("index_risk_pct", 0) / 100
    uncovered = (b["need_per_year"] * b["horizon_years"] - covered) * b["fallback_unit_price"]
    need = b["need_lead_time_days"]
    return {
        "price": spend,
        "uncovered_need": uncovered,
        "fallback_risk": uncovered * b.get("fallback_risk_pct", 0) / 100,
        "payment_terms": spend * b["interest_rate"] * (b["reference_payment_days"] - t["payment_days"]) / 360,
        "freight": committed * b["freight_eur_per_unit"][t["incoterm"]],
        "late_delivery": b.get("late_cost_per_day", 0) * max(0, t["lead_time_days"] - need),
        "quality": committed * (t.get("ppm_commitment") or 0) / 1e6 * defect_cost,
        "tooling": t.get("tooling_eur") or 0.0,
        "index_clause": index,
        "index_risk": index_risk,
        "relationship": relationship_cost(case, t, supplier=supplier),
    }


def total_cost(case, terms, standard=None, supplier=None):
    """C in EUR; infinite for terms without a price (e.g. a supplier that quotes none), so such a
    sheet is never the cheapest and never beats an alternative."""
    if closing_terms(case, terms, standard).get("unit_price") is None:
        return math.inf
    return round(sum(cost_breakdown(case, terms, standard, supplier).values()), 2)


def score(c_open, c_deal, c_best):
    if c_deal is None:
        return 0.0
    if c_open - c_best <= 0.01:  # no room to negotiate: matching the best is full marks
        return 1.0 if c_deal <= c_best + 0.01 else 0.0
    return min(1.0, max(0.0, (c_open - c_deal) / (c_open - c_best)))


def must_haves_ok(case, terms, standard=None):
    t = closing_terms(case, terms, standard)
    for m in case["buyer"].get("must_haves", []):
        value = t.get(m["field"])
        if value is None and m["op"] not in ("==", "!="):
            return False
        if not OPS[m["op"]](value, m["value"]):
            return False
    return True


def snap(case, field, value):
    """The allowed value closest to `value` (case `term_options`), else `value` unchanged."""
    options = case.get("term_options", {}).get(field)
    if not options or value in options:
        return value
    if isinstance(value, int | float) and all(isinstance(o, int | float) for o in options):
        return min(options, key=lambda o: (abs(o - value), o))
    return options[0]


def complete_offer(case, terms):
    """A valid term sheet: exactly the negotiable fields, gaps from the buyer's plan, snapped."""
    plan = closing_terms(case, {"unit_price": None})
    freight = case["buyer"]["freight_eur_per_unit"]
    plan["incoterm"] = min(freight, key=freight.get)  # when asking, ask for the cheapest freight
    out = {}
    for field in case["negotiable"]:
        value = terms.get(field, plan.get(field))
        if value is None and case.get("term_options", {}).get(field):
            value = case["term_options"][field][0]
        value = snap(case, field, value)
        out[field] = round(value, 2) if field == "unit_price" and value is not None else value
    return out
"""Play cases with an agent against the arena over HTTP - the hosted arena (practice, sandbox,
final) or `arena-sim`, the local contract simulator. Both speak the same API.

An agent is any object with `decide(case, threads) -> {"supplier_id": ..., "message": {...}}`:
  threads: {supplier_id: [message, ...]} - every e-mail so far, both directions, in order;
           supplier attachments carry their text under "text" (see `docs.read_document`).
  message: subject, body, up to 3 term sheets, refs - or an "action" that closes the case:
           {"type": "accept", "term_sheet_id": ...} or {"type": "walk_away"}.
"""

import functools
import logging
import re
import threading
import time
from concurrent.futures import ThreadPoolExecutor

from .client import ArenaError
from .cost import must_haves_ok, total_cost
from .docs import read_document, standard_terms

log = logging.getLogger("arena")

ENDED = {"walked_away", "no_bid"}
# A message later than this after the supplier's last one counts as a timeout.
MOVE_LIMIT_S = 60
# In the Live Final, close this long before the wave's cap - or the slowest round of the case so far
# (your decision plus a supplier reply of up to about a minute) plus a margin, if that is longer.
CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S = 90, 15
RUNNING = re.compile(r"one session per case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def fetch_documents(table, message):
    """Download every attachment of a supplier message and add its text."""
    for att in message.get("attachments") or []:
        if att.get("attachment_id") and "text" not in att:
            att["text"] = read_document(att["name"], table.attachment(att["attachment_id"]))
    return message


def closing_move(case, threads):
    """Accept the cheapest standing term sheet that keeps the must-haves and beats the alternative
    (C with each supplier's standard terms), else walk away - what to do when time runs out."""
    alt = case["buyer"].get("alternative") or {}
    c_alt = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else float("inf")
    best = None
    for sid in live_threads(threads):
        sheet_id, terms = standing(threads[sid])
        std = standard_terms(threads[sid])
        if sheet_id and must_haves_ok(case, terms, std) and (c := total_cost(case, terms, std)) < c_alt:
            best = min(best or (c, sid, sheet_id), (c, sid, sheet_id))
    if best is None:
        return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}
    return {"supplier_id": best[1], "message": {"action": {"type": "accept", "term_sheet_id": best[2]}}}


def play(table, case_id, agent, deadline=None):
    """Play one case to its end. `deadline` (time.time(), or a function returning it): a Live Final
    wave's cap - shortly before it, `closing_move` closes the case so it does not end without a deal."""
    case, threads = table.open(case_id)
    if getattr(table, "done", None):  # resumed a case that had already ended
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    slowest = 0.0  # the longest round so far: decision + the supplier's reply
    while live_threads(threads):
        t0 = time.monotonic()
        cap = deadline() if callable(deadline) else deadline
        if cap and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S):
            log.info("%s: the wave's cap is near - closing", case_id)
            decision = closing_move(case, threads)
        else:
            decision = agent.decide(case, threads)
        if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
            log.warning("decision took %.1fs - the limit is %ss per message", took, MOVE_LIMIT_S)
        sid, msg = decision["supplier_id"], decision["message"]
        try:
            if msg.get("action"):
                log.info("%s %s", sid, msg["action"])
                return table.close(sid, msg)
            reply = table.send(sid, msg)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)  # e.g. late, or the thread or the case has ended
            if msg.get("action") and "result" not in reply:  # the case goes on: decide again
                threads[sid].append(fetch_documents(table, reply))
                continue
        if "result" in reply:  # the reply ended the case, e.g. the last supplier walked away
            return reply["result"]
        threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
        slowest = max(slowest, time.monotonic() - t0)
        log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
    return table.result()


def hosted(cases):
    """The cases you can play: those marked hosted, or all of them if the list has no marker."""
    if any(HOSTED_FIELD in c for c in cases):
        return [c for c in cases if c.get(HOSTED_FIELD)]
    return cases


def quota_used_up(error):
    """The practice quota's 429 ("practice limit: …"): retrying does not help before it resets."""
    return isinstance(error, ArenaError) and error.status == 429 and str(error.detail).startswith("practice limit")


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Play many cases at once (e.g. every practice case). `new_table()` and `new_agent()` give
    each case its own table and agent. Once the practice quota is used up, no further case starts.
    Returns {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)  # e.g. not hosted for practice
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap, wait
    for the next. Keep it running from before the first wave until the last has closed; it returns
    after `waves` waves have closed and every case has finished: {case_id: result or exception}."""
    started, closed, caps = {}, set(), {}  # caps: wave -> its cap as time.time()

    def one(case, deadline):
        try:
            return play(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:  # each wave has its own cap; follow an extension
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}
"""Read the documents suppliers attach: PDF and XLSX to text, a quote PDF to structured terms."""

import io
import re

LABELS = {
    "Unit price (EUR)": "unit_price",
    "Payment terms (days net)": "payment_days",
    "Lead time (days)": "lead_time_days",
    "Volume per year (pcs)": "volume_per_year",
    "Contract term (months)": "contract_months",
    "Price valid from": "effective_date",
    "Index clause": "index_clause",
    "Incoterm": "incoterm",
    "Tooling (EUR)": "tooling_eur",
    "Quality commitment (ppm)": "ppm_commitment",
    "Chargeback per complaint (EUR)": "chargeback_eur_per_complaint",
}
SECTIONS = {
    "Offered terms": "stated",
    "Our standard terms": "standard",
    "Terms fixed by your enquiry": "fixed",
    "Agreed terms": "agreed",
}
CLAUSE = re.compile(r"(\S+), (\d+)% material, deadband ([\d.]+) %, base (\S+)")


def read_document(name, data):
    """The text of an attachment: PDF pages, XLSX rows (formulas as written), or plain text."""
    if name.endswith(".pdf"):
        from pypdf import PdfReader

        return "\n".join(p.extract_text() for p in PdfReader(io.BytesIO(data)).pages)
    if name.endswith(".xlsx"):
        from openpyxl import load_workbook

        wb = load_workbook(io.BytesIO(data))
        return "\n".join(
            f"[{ws.title}]\n"
            + "\n".join(" | ".join("" if v is None else str(v) for v in row) for row in ws.iter_rows(values_only=True))
            for ws in wb.worksheets
        )
    return data.decode("utf-8", "replace")


def _value(field, text):
    if field == "index_clause":
        m = CLAUSE.match(text)
        if not m:
            return None
        series, share, deadband, base = m.groups()
        return {
            "series": series,
            "material_share": int(share) / 100,
            "deadband_pct": float(deadband),
            "base_month": base,
        }
    if field in ("effective_date", "incoterm"):
        return text
    return float(text) if "eur" in field or field == "unit_price" else int(float(text))


def quote_terms(text):
    """Terms per section of a quote or order confirmation PDF: stated, standard, fixed, agreed."""
    out, section = {}, None
    for line in text.splitlines():
        line = line.strip()
        section = next((key for head, key in SECTIONS.items() if line.startswith(head)), section)
        label = next((lab for lab in LABELS if line.startswith(lab + " ")), None)
        if section and label:
            out.setdefault(section, {})[LABELS[label]] = _value(LABELS[label], line[len(label) :].strip())
    return out


def standard_terms(events):
    """The supplier's standard terms from the latest quote PDF in a thread (empty if none)."""
    for msg in reversed(events):
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote") and att.get("text"):
                return quote_terms(att["text"]).get("standard", {})
    return {}
"""Read-only access to the data package: SQL, lookup by citable ID, documents, practice cases -
plus the Sunday release (new news, letters and a memo) once you have downloaded it."""

import csv
import json
import os
import sqlite3
from functools import cached_property
from pathlib import Path

MAX_ROWS = 200
RELEASE = "release-sunday"


class DataPackage:
    def __init__(self, root, release=None):
        """`root`: the unpacked package. `release`: the unpacked Sunday release (default: a
        `release-sunday` folder inside or next to the package, or ARENA_RELEASE), if present."""
        self.root = Path(root).expanduser().resolve()
        # facts.json holds every citable fact with the fields the arena checks claims against.
        own = self.root / "facts.json"
        facts = [own] if own.is_file() else [p for p in sorted(self.root.rglob("facts.json")) if RELEASE not in p.parts]
        self.facts = json.loads(facts[0].read_text(encoding="utf-8")) if facts else {}
        release = release or os.environ.get("ARENA_RELEASE")
        candidates = [Path(release).expanduser()] if release else [self.root / RELEASE, self.root.parent / RELEASE]
        self.release = next((p.resolve() for p in candidates if (p / "facts.json").is_file()), None)
        if self.release:  # new IDs only: nothing in the package changes
            self.facts |= json.loads((self.release / "facts.json").read_text(encoding="utf-8"))
        dbs = sorted(self.root.rglob("*.sqlite")) + sorted(self.root.rglob("*.db"))
        if not dbs and not facts:
            raise FileNotFoundError(f"no facts.json or .sqlite under {self.root}")
        self.db = None
        if dbs:
            self.db = sqlite3.connect(f"file:{dbs[0]}?mode=ro", uri=True, check_same_thread=False)
            self.db.row_factory = sqlite3.Row
            self.db.execute("PRAGMA query_only = ON")

    def tables(self):
        """{table: {"columns": [...], "rows": n}}"""
        if self.db is None:
            return {}
        names = [r[0] for r in self.db.execute("SELECT name FROM sqlite_master WHERE type = 'table' ORDER BY name")]
        return {
            t: {
                "columns": [f"{c[1]} {c[2]}".strip() for c in self.db.execute(f'PRAGMA table_info("{t}")')],
                "rows": self.db.execute(f'SELECT count(*) FROM "{t}"').fetchone()[0],
            }
            for t in names
        }

    def query(self, sql, params=(), limit=MAX_ROWS):
        if self.db is None:
            raise ValueError("this package has no SQLite file")
        if sql.lstrip().split(None, 1)[0].lower() not in {"select", "with"}:
            raise ValueError("read-only: SELECT or WITH statements only")
        cur = self.db.execute(sql, params)
        return [dict(r) for r in cur.fetchmany(limit)]

    @cached_property
    def _ids(self):
        # A table's citable ID sits in its `id` column, else in its first column.
        index = {}
        for t, meta in self.tables().items():
            cols = [c.split()[0] for c in meta["columns"]]
            key = "id" if "id" in cols else cols[0]
            for row in self.db.execute(f'SELECT * FROM "{t}"'):
                value = row[key]
                if isinstance(value, str) and ":" in value:
                    index[value] = {"table": t, **dict(row)}
        for path in sorted(self.release.glob("data/*.csv")) if self.release else []:  # not in the SQLite
            with path.open(encoding="utf-8", newline="") as f:
                for row in csv.DictReader(f):
                    index[row["id"]] = {"table": path.stem, **row, "root": str(self.release)}
        return index

    def lookup(self, ref):
        """The fact behind a citable ID (from facts.json, else its table row), or None."""
        return self.facts.get(ref) or self._ids.get(ref)

    def ids(self, prefix):
        """All citable IDs starting with `prefix`, sorted, e.g. ids("idx:GP19-245113@")."""
        return sorted(i for i in self.facts.keys() | self._ids.keys() if i.startswith(prefix))

    def document(self, ref):
        """A document's text by ID (row with a path or body column) or by path in the package."""
        row, base = self._ids.get(ref) or self.facts.get(ref), self.root
        if row:
            for col in ("body", "text", "content"):
                if row.get(col):
                    return row[col]
            base = Path(row.get("root") or self.root)
            ref = next((row[c] for c in ("path", "file") if row.get(c)), None)
            if ref is None:
                return json.dumps(row, ensure_ascii=False)
        path = (base / ref).resolve()
        if not path.is_relative_to(base) or not path.is_file():
            raise FileNotFoundError

