"""Dossier Builder: everything the data package says about the case's suppliers and parts.

Deterministic SQL plus keyword tagging of notes, letters, news and quote remarks (see `priors`).
Reads the Sunday release (CSV rows, not in the SQLite) when it is present.
"""

import csv
import re
from pathlib import Path

from .priors import ARCHETYPES

NOTE_CHARS = 220
TRIGGER_CHARS = 1500


def _rows(pkg, sql, params=(), limit=200):
    try:
        return pkg.query(sql, params, limit=limit)
    except Exception:
        return []


def _one(pkg, sql, params=()):
    rows = _rows(pkg, sql, params, limit=1)
    return rows[0] if rows else {}


def _read(base, rel):
    try:
        path = (Path(base) / rel).resolve()
        if path.is_relative_to(Path(base).resolve()) and path.is_file():
            return path.read_text(encoding="utf-8")
    except Exception:
        pass
    return ""


def _release_rows(pkg, table):
    if not getattr(pkg, "release", None):
        return []
    path = Path(pkg.release) / "data" / f"{table}.csv"
    if not path.is_file():
        return []
    try:
        with path.open(encoding="utf-8", newline="") as f:
            return list(csv.DictReader(f))
    except Exception:
        return []


def _sentence(text, phrase):
    """The sentence around a matched phrase, for evidence in prompts."""
    low = text.lower()
    i = low.find(phrase)
    if i < 0:
        return ""
    start = max(low.rfind(".", 0, i), low.rfind("\n", 0, i)) + 1
    end = min([j for j in (low.find(".", i), low.find("\n", i)) if j >= 0] or [len(text)])
    return re.sub(r"\s+", " ", text[start : end + 1]).strip()[:NOTE_CHARS]


def tag_text(text):
    """[(tag, phrase, sentence)] for every archetype phrase found in `text`."""
    low = (text or "").lower()
    hits = []
    for tag, spec in ARCHETYPES.items():
        for phrase in spec["phrases"]:
            if phrase in low:
                hits.append((tag, phrase, _sentence(text, phrase)))
                break
    return hits


def supplier_dossier(pkg, sid, parts):
    d = {"supplier_id": sid, "tags": [], "evidence": {}, "notes": []}

    def tag(name, ref, note=None):
        if name not in d["tags"]:
            d["tags"].append(name)
        d["evidence"].setdefault(name, [])
        if ref and ref not in d["evidence"][name]:
            d["evidence"][name].append(ref)
        if note and len(d["notes"]) < 8 and note not in [n["text"] for n in d["notes"]]:
            d["notes"].append({"ref": ref, "tag": name, "text": note})

    master = _one(pkg, "SELECT * FROM suppliers WHERE id=?", (sid,))
    d["name"] = master.get("name") or sid
    d["country"] = master.get("country")
    d["category"] = master.get("category")
    d["contract_id"] = master.get("contract_id")
    intel = _one(pkg, "SELECT * FROM supplier_intel WHERE supplier_id=?", (sid,))
    d["intel"] = {
        k: intel.get(k)
        for k in ("owner_type", "group_parent", "staff", "turnover_band", "equity_ratio_pct", "credit_index")
        if intel.get(k) not in (None, "")
    }
    if intel.get("credit_index") is not None and intel.get("credit_index_12m_ago") is not None:
        d["intel"]["credit_index_change_12m"] = intel["credit_index"] - intel["credit_index_12m_ago"]
        if d["intel"]["credit_index_change_12m"] >= 40:  # a higher credit index is worse
            tag("cash_short", f"sup:{sid.split(':')[-1]}", "Credit index worsened markedly in 12 months.")
    if intel.get("owner_type") in ("family", "founder"):
        d["intel"]["family_or_founder"] = True

    hist = _rows(
        pkg,
        "SELECT date, part_id, type, asked_pct, settled_pct, note FROM negotiation_history "
        "WHERE supplier_id=? ORDER BY date DESC",
        (sid,),
        limit=8,
    )
    d["history"] = hist[:6]
    settled = [h["settled_pct"] for h in hist if h.get("settled_pct") is not None]
    asked = [h["asked_pct"] for h in hist if h.get("asked_pct") is not None]
    d["history_avg"] = {
        "asked_pct": round(sum(asked) / len(asked), 2) if asked else None,
        "settled_pct": round(sum(settled) / len(settled), 2) if settled else None,
    }

    sc = _one(
        pkg,
        "SELECT id, quarter, otd_pct, ppm, colour, score FROM scorecards WHERE supplier_id=? ORDER BY quarter DESC",
        (sid,),
    )
    d["scorecard"] = sc
    late = _one(
        pkg,
        "SELECT AVG(julianday(paid_date)-julianday(due_date)) AS late FROM invoices "
        "WHERE supplier_id=? AND paid_date IS NOT NULL",
        (sid,),
    )
    d["late_payment_days"] = round(late["late"], 1) if late.get("late") is not None else None

    news = _rows(
        pkg,
        "SELECT id, date, topic, headline FROM news WHERE supplier_id=? AND topic NOT IN ('noise','market') "
        "ORDER BY date DESC",
        (sid,),
        limit=10,
    )
    news += [
        {k: r.get(k) for k in ("id", "date", "topic", "headline")}
        for r in _release_rows(pkg, "news")
        if r.get("supplier_id") == sid and r.get("topic") not in ("noise", "market")
    ]
    d["news"] = news
    for n in news:
        for name, spec in ARCHETYPES.items():
            if n.get("topic") in spec["news"]:
                tag(name, n.get("id"), n.get("headline"))

    docs = _rows(
        pkg,
        "SELECT id, date, kind, subject, file FROM documents WHERE supplier_id=? AND id NOT LIKE '%-N' "
        "ORDER BY date DESC",
        (sid,),
        limit=40,
    )
    for doc in docs:
        doc["base"] = pkg.root
    for r in _release_rows(pkg, "documents"):
        if r.get("supplier_id") == sid and not str(r.get("id", "")).endswith("-N"):
            docs.append({**{k: r.get(k) for k in ("id", "date", "kind", "subject", "file")}, "base": pkg.release})
    d["documents"] = [{k: doc.get(k) for k in ("id", "date", "kind", "subject")} for doc in docs[:12]]
    for doc in docs:
        text = _read(doc["base"], doc.get("file") or "")
        for name, _, sentence in tag_text(text):
            tag(name, doc["id"], sentence)

    quotes = _rows(
        pkg,
        "SELECT id, part_id, quote_date, unit_price, price_unit, payment_days, lead_time_days, incoterm, "
        "remarks FROM quotes WHERE supplier_id=? ORDER BY quote_date DESC",
        (sid,),
        limit=10,
    )
    d["quotes"] = [q for q in quotes if q.get("part_id") in parts][:4] or quotes[:2]
    for q in quotes:
        for name, _, sentence in tag_text(q.get("remarks") or ""):
            tag(name, q["id"], sentence)
    if (d["late_payment_days"] or 0) >= 7:
        tag("unpaid", None, f"We paid its invoices {d['late_payment_days']} days late on average.")
    return d


def part_dossier(pkg, part):
    p = _one(pkg, "SELECT id, description, price_unit, standard_price, material_group FROM parts WHERE id=?", (part,))
    p["cost_drivers"] = _rows(pkg, "SELECT series_id, weight FROM cost_drivers WHERE part_id=?", (part,))
    p["should_cost"] = _rows(
        pkg,
        "SELECT id, supplier_id, unit_cost, price_unit, confidence_pct FROM should_cost WHERE part_id=?",
        (part,),
    )
    return p


def trigger(pkg, case):
    ref = case.get("trigger_doc")
    if not ref:
        return {}
    fact = pkg.facts.get(ref) or {}
    out = {"id": ref, **{k: fact.get(k) for k in ("asked_pct", "asked_price", "days", "effective_date", "title")}}
    row = _one(pkg, "SELECT file FROM documents WHERE id=?", (ref,))
    text = _read(pkg.root, row.get("file") or "")
    if not text:
        for r in _release_rows(pkg, "documents"):
            if r.get("id") == ref:
                text = _read(pkg.release, r.get("file") or "")
    out["text"] = text[:TRIGGER_CHARS]
    return out


def build(case, pkg):
    parts = case.get("parts") or []
    return {
        "suppliers": {sid: supplier_dossier(pkg, sid, parts) for sid in case.get("suppliers") or []},
        "parts": {p: part_dossier(pkg, p) for p in parts},
        "trigger": trigger(pkg, case),
    }


def digest(dossier, sid):
    """A compact view of one supplier for the prompt."""
    d = dossier["suppliers"].get(sid) or {}
    return {
        "name": d.get("name"),
        "country": d.get("country"),
        "tags": d.get("tags", []),
        "notes": d.get("notes", [])[:6],
        "intel": d.get("intel", {}),
        "history_avg": d.get("history_avg"),
        "history": [
            {k: h.get(k) for k in ("date", "type", "asked_pct", "settled_pct", "note")} for h in d.get("history", [])[:4]
        ],
        "scorecard": d.get("scorecard"),
        "news": [{k: n.get(k) for k in ("date", "topic", "headline")} for n in d.get("news", [])[:4]],
        "quote_remarks": [q.get("remarks") for q in d.get("quotes", []) if q.get("remarks")][:3],
        "late_payment_days": d.get("late_payment_days"),
    }

"""Claim Cataloguer: data arguments that pass the arena's check, with the figure computed in code.

Rules follow brief/api.md "What counts": one argument per sentence, the figure in the same sentence
as its IDs, tolerance ±0.5 pp / ±0.5 %, at most 3 checked per message, each ID once per case.
Only claims that help the buyer are listed; the model chooses among them by `cid`.
"""

import re
from functools import lru_cache

ID_RE = re.compile(r"\b(?:po|idx|sc|ctr|doc|quote|offer|qn|fc|cost|news|rfq|sup|part):[\w.\-@#]+")
FAVOURABLE_NEWS = {"free_capacity", "short_time_work"}
MAX_PER_MESSAGE = 3


def ids_in(text):
    return [m.rstrip(".,;)") for m in ID_RE.findall(text or "")]


def used_ids(threads):
    """IDs already cited in this case (refs and bodies of every buyer message), per supplier."""
    out = {}
    for sid, events in threads.items():
        seen = out.setdefault(sid, set())
        for m in events:
            if m.get("from") == "buyer":
                seen.update(m.get("refs") or [])
                seen.update(ids_in(m.get("body")))
    return out


@lru_cache(maxsize=4)
def _series_months(facts_id):
    return {}


def series_index(facts):
    """{series: sorted months} from the idx facts (cached per facts object)."""
    key = id(facts)
    cache = _series_months(key)
    if not cache:
        for ref, fact in facts.items():
            if ref.startswith("idx:") and isinstance(fact, dict) and fact.get("series") and fact.get("month"):
                cache.setdefault(fact["series"], []).append(fact["month"])
        for months in cache.values():
            months.sort()
    return cache


def _minus_year(month):
    y, m = month.split("-")
    return f"{int(y) - 1}-{m}"


def _pct(x):
    return f"{x:+.1f}%"


def _eur(x):
    return f"EUR {x:.2f}"


def build_catalog(case, facts, dossier, sid, standing_price=None, asked_pct=None):
    """Static claims for one supplier (figures pre-computed and within tolerance)."""
    facts = {**facts, **(case.get("facts") or {})}
    parts = set(case.get("parts") or [])
    out = []

    def add(kind, ids, figure, unit, sentence, supports, strength, reveals=False):
        out.append(
            {
                "kind": kind,
                "ids": ids,
                "figure": figure,
                "unit": unit,
                "sentence": sentence,
                "supports": supports,
                "strength": round(strength, 2),
                "reveals": reveals,
            }
        )

    # Index pairs: series that drive this part's cost, the case's index paths, or IDs in the case refs.
    series = set()
    for part in dossier.get("parts", {}).values():
        series.update(d["series_id"] for d in part.get("cost_drivers", []) if d.get("series_id"))
    series.update((case.get("buyer") or {}).get("index_paths", {}) or {})
    series.update(r.split(":", 1)[1].split("@")[0] for r in case.get("refs") or [] if r.startswith("idx:"))
    months = series_index(facts)
    weights = {}
    for part in dossier.get("parts", {}).values():
        for d in part.get("cost_drivers", []):
            weights[d.get("series_id")] = max(weights.get(d.get("series_id"), 0), d.get("weight") or 0)
    for s in sorted(series):
        later = (months.get(s) or [None])[-1]
        if not later or later < "2025-10":
            continue
        earlier = _minus_year(later)
        a, b = facts.get(f"idx:{s}@{earlier}"), facts.get(f"idx:{s}@{later}")
        if not a or not b or not a.get("value"):
            continue
        change = (b["value"] / a["value"] - 1) * 100
        rounded = round(change, 1)
        # helps the buyer when it rose less than the supplier asks (or fell)
        bar = asked_pct if asked_pct is not None else 2.0
        if rounded >= bar:
            continue
        strength = 0.4 + min(0.5, (bar - rounded) / 10) + min(0.1, weights.get(s, 0) / 3)
        add(
            "idx",
            [f"idx:{s}@{earlier}", f"idx:{s}@{later}"],
            rounded,
            "%",
            f"The {s} index changed {_pct(rounded)} from {earlier} to {later} (idx:{s}@{earlier}, idx:{s}@{later}).",
            "price_down",
            strength,
        )

    # Scorecard: weak delivery or quality of this supplier, latest quarter.
    sc = [(ref, f) for ref, f in facts.items() if ref.startswith(f"sc:{sid.split(':')[-1]}@")]
    if sc:
        ref, f = max(sc, key=lambda x: x[1].get("quarter") or "")
        if f.get("otd_pct") is not None and f["otd_pct"] < 92:
            add(
                "sc",
                [ref],
                round(f["otd_pct"], 1),
                "%",
                f"Your on-time delivery last quarter was {f['otd_pct']:.1f}% ({ref}).",
                "performance",
                0.35 + min(0.4, (92 - f["otd_pct"]) / 40),
            )
        elif f.get("ppm") is not None and f["ppm"] > 500:
            add(
                "sc",
                [ref],
                round(f["ppm"]),
                "ppm",
                f"Your quality last quarter was {round(f['ppm'])} ppm ({ref}).",
                "performance",
                0.35 + min(0.4, f["ppm"] / 10000),
            )

    # Quotes of this case (refs or the alternative): a cheaper price for the same part.
    alt = (case.get("buyer") or {}).get("alternative") or {}
    quote_refs = [r for r in case.get("refs") or [] if r.startswith("quote:")]
    if alt.get("ref") and str(alt["ref"]).startswith("quote:"):
        quote_refs.append(alt["ref"])
    for ref in dict.fromkeys(quote_refs):
        f = facts.get(ref) or {}
        price = f.get("unit_price")
        if price is None or (f.get("part") and f["part"] not in parts) or f.get("supplier") == sid:
            continue
        if f.get("price_unit") not in (None, 1):
            continue
        if standing_price is not None and price >= standing_price:
            continue
        add(
            "quote",
            [ref],
            price,
            "EUR",
            f"We hold a quote for this part at {_eur(price)} per unit ({ref}).",
            "price_down",
            0.7,
            reveals=True,
        )

    # Should-cost: offer far above the estimate.
    for part in parts:
        ref = f"cost:{part.split(':')[-1]}"
        f = facts.get(ref) or {}
        if f.get("unit_cost") and f.get("price_unit") in (None, 1) and standing_price:
            if standing_price > f["unit_cost"] * 1.12:
                add(
                    "cost",
                    [ref],
                    f["unit_cost"],
                    "EUR",
                    f"Our should-cost estimate for this part is {_eur(f['unit_cost'])} per unit ({ref}).",
                    "price_down",
                    0.45,
                    reveals=True,
                )

    # Forecast: rising volume is something to offer.
    for part in parts:
        num = part.split(":")[-1]
        fcs = sorted(r for r in facts if r.startswith(f"fc:{num}@"))
        if fcs:
            f = facts[fcs[-1]]
            if (f.get("change_pct") or 0) >= 3:
                add(
                    "fc",
                    [fcs[-1]],
                    round(f["change_pct"], 1),
                    "%",
                    f"Our forecast for this part is up {f['change_pct']:.1f}% ({fcs[-1]}).",
                    "volume",
                    0.4,
                )

    # Order history: 2-8 recent orders of this part from this supplier at one price, below the offer.
    for part in parts:
        rows = sorted(
            (
                (f.get("date") or "", ref, f)
                for ref, f in facts.items()
                if ref.startswith("po:") and f.get("part") == part and f.get("supplier") == sid
            ),
            reverse=True,
        )
        if len(rows) >= 2 and rows[0][2].get("price_unit") in (None, 1):
            price = rows[0][2].get("unit_price")
            same = [r for r in rows[:8] if r[2].get("unit_price") == price]
            if len(same) >= 2 and price and standing_price and price < standing_price:
                ids = [r[1] for r in same[:4]]
                add(
                    "po",
                    ids,
                    price,
                    "EUR",
                    f"Our recent orders of this part were at {_eur(price)} per unit ({', '.join(ids)}).",
                    "price_down",
                    0.4,
                )

    # News about this supplier that weakens its position.
    for n in (dossier.get("suppliers", {}).get(sid) or {}).get("news", []):
        ref = n.get("id")
        if n.get("topic") in FAVOURABLE_NEWS and ref and (facts.get(ref) or {}).get("supplier") == sid:
            add("news", [ref], None, None, f"We read that you have spare capacity ({ref}).", "volume", 0.3)

    # Notice period: the letter gives less notice than the contract's price clause.
    trig = dossier.get("trigger") or {}
    contract = (dossier.get("suppliers", {}).get(sid) or {}).get("contract_id")
    if trig.get("id") and trig.get("days") is not None and contract:
        doc = facts.get(trig["id"]) or {}
        if doc.get("supplier") == sid:
            clauses = [
                (ref, f)
                for ref, f in facts.items()
                if ref.startswith(f"ctr:{contract}#") and f.get("type") == "price" and f.get("days")
            ]
            ref, f = clauses[0] if clauses else (f"ctr:{contract}", facts.get(f"ctr:{contract}") or {})
            if f.get("days") and trig["days"] < f["days"]:
                add(
                    "notice",
                    [trig["id"], ref],
                    trig["days"],
                    "days",
                    f"Your letter gives {trig['days']} days' notice ({trig['id']}), but our contract requires "
                    f"{f['days']} days ({ref}).",
                    "timing",
                    0.8,
                )

    out.sort(key=lambda c: -c["strength"])
    for i, c in enumerate(out, 1):
        c["cid"] = f"C{i}"
    return out


def rival_claims(case, threads, sid, ledgers, start):
    """RFQ: another bidder's standing price below this supplier's (reveals it - use deliberately)."""
    out = []
    mine = (ledgers.get(sid) or {}).get("price")
    for other, led in ledgers.items():
        if other == sid or not led.get("offer_id") or led.get("price") is None or mine is None:
            continue
        if led["price"] < mine:
            out.append(
                {
                    "kind": "offer",
                    "ids": [led["offer_id"]],
                    "figure": led["price"],
                    "unit": "EUR",
                    "sentence": f"Another bidder offers this part at {_eur(led['price'])} per unit ({led['offer_id']}).",
                    "supports": "price_down",
                    "strength": 0.75,
                    "reveals": True,
                }
            )
    out.sort(key=lambda c: c["figure"])
    for i, c in enumerate(out[:1], start):
        c["cid"] = f"C{i}"
    return out[:1]


def available(catalog, used, blocked_kinds=()):
    """Claims not yet cited in this thread and not of a kind the run learned to avoid."""
    return [c for c in catalog if not (set(c["ids"]) & used) and c["kind"] not in blocked_kinds]

"""Offer Builder: valid term sheets of equal value to the supplier, cheapest for us first.

For every combination of the non-price levers the price is solved so that the package is worth a
target amount to the supplier (`cost.supplier_value`: a cash-short supplier values early payment).
The target walks from our aspiration towards the supplier's standing offer along a concession
schedule; `trade` packages are worth exactly as much to it as its own offer but cost us less.
"""

import itertools
import math

from arena_kit.cost import RELATIONSHIP_GOALS, must_haves_ok, supplier_value, total_cost

from . import priors

MAX_COMBOS = 300
PER_LEVEL = 3


def lever_domains(case, std):
    """{field: [allowed values]} for the non-price negotiable fields, or None if one has none."""
    out = {}
    for field in case["negotiable"]:
        if field == "unit_price":
            continue
        values = list(case.get("term_options", {}).get(field) or [])
        if field in std and std[field] not in values:
            values.append(std[field])
        if not values:
            return None
        out[field] = values
    return out


def _prune(domains, base):
    """Keep the product small: at most 4 values per field, always including the supplier's own."""
    while math.prod(len(v) for v in domains.values()) > MAX_COMBOS:
        field = max(domains, key=lambda f: len(domains[f]))
        values = domains[field]
        keep = [base.get(field)] if base.get(field) in values else []
        rest = [v for v in values if v not in keep]
        step = max(1, len(rest) // 3)
        domains[field] = keep + rest[::step][:3]
        if len(domains[field]) == len(values):
            break
    return domains


def supplier_standard(case, led):
    """Its standard terms for valuation: stated at the opening, then the standard section, plan gaps."""
    b = case["buyer"]
    std = {**{k: v for k, v in (led.get("stated_open") or {}).items() if k != "unit_price"}, **(led.get("std") or {})}
    std.setdefault("payment_days", b["reference_payment_days"])
    if "incoterm" not in std:
        std["incoterm"] = case.get("fixed_terms", {}).get("incoterm") or "EXW"
    return std


def supplier_model(case, led, tags, dossier_sup, parts_dossier):
    """Our estimate of the supplier for `supplier_value` / the relationship term."""
    model = {"standard": supplier_standard(case, led), "interest_rate": priors.rate_for(tags), "usual_rate": 0.07}
    b = case["buyer"]
    if b.get("category_goal") in RELATIONSHIP_GOALS:
        full = None
        for part in parts_dossier.values():
            for sc in part.get("should_cost", []):
                if sc.get("unit_cost") and sc.get("price_unit") in (None, 1):
                    full = sc["unit_cost"] if full is None else min(full, sc["unit_cost"])
        if full is None and led.get("price"):
            full = led["price"] * (1 - ((b.get("sustainable_margin_pct") or 8) + 2) / 100)
        if led.get("breakdown_total"):
            full = led["breakdown_total"]
        if full:
            model["full_cost"] = full
    return model


def _value(case, terms, model):
    try:
        return supplier_value(case, terms, model)
    except Exception:
        return None


def solve_price(case, levers, model, target):
    """Unit price (2 decimals) that makes the package worth `target` to the supplier."""
    v0 = _value(case, {**levers, "unit_price": 0.0}, model)
    v1 = _value(case, {**levers, "unit_price": 1.0}, model)
    if v0 is None or v1 is None or v1 - v0 <= 1e-9:
        return None
    price = (target - v0) / (v1 - v0)
    return round(price, 2) if price > 0 else None


def cost(case, terms, std, model):
    try:
        sup = model if case["buyer"].get("category_goal") in RELATIONSHIP_GOALS and model.get("full_cost") else None
        c = total_cost(case, terms, std, sup)
        return c if math.isfinite(c) else None
    except Exception:
        return None


def anchor_price(case, led, tags, dossier, drop):
    """First ask: the standing price minus `drop`, never below a plausible cost floor."""
    standing = led["price"]
    b = case["buyer"]
    factor = 1.0
    for t in tags:
        factor *= {"full_order_book": 0.5, "not_strategic": 0.7, "price_frozen": 0.5, "spare_capacity": 1.3,
                   "weak_costing": 1.2, "cash_short": 0.8}.get(t, 1.0)
    target = standing * (1 - min(0.35, drop * factor))
    current = b.get("current_unit_price")
    if current and case.get("type") in ("price_increase", "renewal", "raw_material") and current < standing:
        target = min(target, current)
    floors = [
        sc["unit_cost"] * 1.03
        for part in dossier.get("parts", {}).values()
        for sc in part.get("should_cost", [])
        if sc.get("unit_cost") and sc.get("price_unit") in (None, 1)
    ]
    if floors:
        target = max(target, min(floors))
    return round(min(target, standing), 2)


def schedule(k, horizon):
    """Share of the way from our aspiration to its offer after k of our messages (slow early)."""
    if horizon <= 1:
        return 1.0
    return min(1.0, (k / (horizon - 1)) ** 2)


def build_menu(case, led, model, std, v_asp, v_stand, levels, must_beat):
    """Candidates [{mid, level, terms, c, saving, price, changes}] for the given {level: share} map."""
    domains = lever_domains(case, std)
    if domains is None or v_asp is None or v_stand is None:
        return []
    base = model["standard"]
    domains = _prune(domains, base)
    names = list(domains)
    combos = [dict(zip(names, values, strict=True)) for values in itertools.product(*domains.values())] or [{}]
    menu, seen = [], set()
    for level, share in levels.items():
        target = v_asp + (v_stand - v_asp) * share
        found = []
        for levers in combos:
            price = solve_price(case, levers, model, target)
            if price is None:
                continue
            terms = {**levers, "unit_price": price}
            terms = {f: terms[f] for f in case["negotiable"]}
            if not must_haves_ok(case, terms, std):
                continue
            c = cost(case, terms, std, model)
            if c is None or c >= must_beat - 0.5:
                continue
            found.append((c, terms))
        found.sort(key=lambda x: x[0])
        picked = 0
        for c, terms in found:
            key = tuple(sorted((k, str(v)) for k, v in terms.items()))
            profile = tuple(sorted((k, str(v)) for k, v in terms.items() if k != "unit_price"))
            if key in seen or (picked and profile in {m["profile"] for m in menu if m["level"] == level}):
                continue
            seen.add(key)
            menu.append(
                {
                    "level": level,
                    "terms": terms,
                    "c": round(c, 2),
                    "saving": round(must_beat - c, 2),
                    "price": terms.get("unit_price"),
                    "changes": {k: v for k, v in terms.items() if k != "unit_price" and base.get(k) != v},
                    "profile": profile,
                }
            )
            picked += 1
            if picked >= PER_LEVEL:
                break
    for i, m in enumerate(menu, 1):
        m["mid"] = f"M{i}"
        m.pop("profile", None)
    return menu


def describe(case, terms):
    """One human line per sheet, written by code (figures never come from the model)."""
    parts = [f"unit price EUR {terms['unit_price']:.2f}"] if terms.get("unit_price") is not None else []
    labels = {
        "payment_days": lambda v: f"payment {v} days net",
        "lead_time_days": lambda v: f"lead time {v} days",
        "volume_per_year": lambda v: f"{v} pieces a year",
        "contract_months": lambda v: "single order" if v == 0 else f"contract {v} months",
        "effective_date": lambda v: f"valid from {v}",
        "incoterm": lambda v: f"Incoterm {v}",
        "tooling_eur": lambda v: f"tooling EUR {v:,.0f}",
        "ppm_commitment": lambda v: f"quality commitment {v} ppm",
        "chargeback_eur_per_complaint": lambda v: f"chargeback EUR {v} per complaint",
        "index_clause": lambda v: "no index clause"
        if not v
        else f"index clause on {v.get('series')} ({round(100 * v.get('material_share', 0))}% material)",
    }
    for field in case["negotiable"]:
        if field != "unit_price" and field in terms:
            fmt = labels.get(field, lambda v, f=field: f"{f.replace('_', ' ')} {v}")
            try:
                parts.append(fmt(terms[field]))
            except Exception:
                parts.append(f"{field} {terms[field]}")
    return ", ".join(parts)

"""Observer: one ledger per supplier thread - what it offers, how it moved, how our claims landed."""

import math

from arena_kit.cost import total_cost
from arena_kit.docs import quote_terms, standard_terms
from arena_kit.harness.validation import acceptable
from arena_kit.play import ENDED, latest, moves_left, standing

TEXT_CHARS = 1200
ATTACH_CHARS = 1500


def _quote_sections(events):
    """Sections of the first readable quote PDF in the thread (the opening offer)."""
    for msg in events:
        for att in msg.get("attachments") or []:
            if att.get("name", "").startswith("quote") and att.get("text"):
                try:
                    return quote_terms(att["text"])
                except Exception:
                    return {}
    return {}


def build(case, threads):
    out = {}
    for sid, events in threads.items():
        led = {"supplier_id": sid}
        try:
            last = latest(events)
        except StopIteration:
            continue
        offer_id, terms = standing(events)
        led.update(offer_id=offer_id, terms=terms, price=terms.get("unit_price"), status=last.get("status"))
        led["ended"] = last.get("status") in ENDED
        led["std"] = standard_terms(events)
        led["stated_open"] = _quote_sections(events).get("stated", {})
        try:
            c = total_cost(case, terms, led["std"]) if terms else math.inf
        except Exception:
            c = math.inf
        led["c"] = c if math.isfinite(c) else None
        supplier_msgs = [m for m in events if m.get("from") != "buyer"]
        buyer_msgs = [m for m in events if m.get("from") == "buyer"]
        led["prices"] = [
            (m.get("term_sheets") or [{}])[0].get("terms", {}).get("unit_price") for m in supplier_msgs
        ]
        led["statuses"] = [m.get("status") for m in supplier_msgs]
        led["rounds"] = len(buyer_msgs)
        led["moves_left"] = moves_left(case, events)
        led["our_sheets"] = [[s.get("terms", {}) for s in m.get("term_sheets") or []] for m in buyer_msgs]
        led["missing_fields"] = last.get("missing_fields") or []
        led["claim_results"] = [r.get("result") for r in last.get("claim_results") or []]
        led["claims_total"] = {}
        for m in supplier_msgs:
            for r in m.get("claim_results") or []:
                led["claims_total"][r.get("result")] = led["claims_total"].get(r.get("result"), 0) + 1
        led["from"] = last.get("from")
        led["body"] = (last.get("body") or "")[:TEXT_CHARS]
        led["signals"] = last.get("signals") or {}
        prices = [p for p in led["prices"] if p]
        led["move_pct"] = round((prices[-2] - prices[-1]) / prices[-2] * 100, 2) if len(prices) >= 2 else None
        led["total_move_pct"] = round((prices[0] - prices[-1]) / prices[0] * 100, 2) if len(prices) >= 2 else 0.0
        first_final = next((i for i, s in enumerate(led["statuses"]) if s == "final_offer"), None)
        # supplier message i answers buyer message i-1 (message 0 is the opening quote)
        led["pushes_after_final"] = 0 if first_final is None else max(0, len(buyer_msgs) - first_final)
        led["attachments"] = [
            {"name": a.get("name"), "text": (a.get("text") or "")[:ATTACH_CHARS]}
            for a in last.get("attachments") or []
            if a.get("text") and not a.get("name", "").startswith("quote")
        ]
        led["breakdown"] = any("breakdown" in (a.get("name") or "").lower() for m in supplier_msgs
                               for a in m.get("attachments") or [])
        try:
            led["acceptable"] = bool(offer_id) and not led["ended"] and acceptable(case, events)
        except Exception:
            led["acceptable"] = False
        out[sid] = led
    return out


def digest(led):
    """Compact view for the prompt."""
    return {
        "status": led.get("status"),
        "from": led.get("from"),
        "standing_terms": led.get("terms"),
        "standing_cost_eur": led.get("c"),
        "price_path": led.get("prices"),
        "status_path": led.get("statuses"),
        "our_messages": led.get("rounds"),
        "moves_left": led.get("moves_left"),
        "last_move_pct": led.get("move_pct"),
        "claims_last": led.get("claim_results"),
        "claims_total": led.get("claims_total"),
        "missing_fields": led.get("missing_fields"),
        "standard_terms": led.get("std"),
        "signals": led.get("signals"),
        "latest_email": led.get("body"),
        "attachments": led.get("attachments"),
    }

"""Critic: turns a chosen move into a safe e-mail. Figures come from code; the model's prose is linted.

Placeholders the model may use: {{CLAIM:C1}} (the claim's sentence), {{SHEETS}} (one line per term
sheet), {{QUESTIONS}}. Model sentences with digits, currency, % or data IDs are dropped, and so are
sentences that leak urgency, a budget, a missing alternative or a target.
"""

import re

from .claims import ID_RE, MAX_PER_MESSAGE
from .offers import describe

PLACEHOLDER = re.compile(r"\{\{\s*(CLAIM:C\d+|SHEETS|QUESTIONS)\s*\}\}")
LEAKS = re.compile(
    r"\b(urgent|urgently|asap|as soon as possible|deadline|budget|no alternative|only supplier|no other supplier|"
    r"single source|must have|desperate|target price|walk away|our limit|maximum we can|running out|"
    r"production stop|line stop|critical shortage)\b",
    re.IGNORECASE,
)
FIGURE = re.compile(r"\d|€|%|\beur\b", re.IGNORECASE)
BODY_LIMIT = 7000
SUBJECT_LIMIT = 200
LETTERS = "ABC"


def _sentences(text):
    return [s for s in re.split(r"(?<=[.!?])\s+|\n", text or "") if s.strip()]


def lint(text):
    """Model prose without figures, IDs or leaks; placeholders survive. Returns (text, issues)."""
    issues, kept = [], []
    for line in (text or "").splitlines():
        out = []
        for sentence in _sentences(line):
            bare = PLACEHOLDER.sub("", sentence)
            if LEAKS.search(bare):
                issues.append("leak")
                continue
            if FIGURE.search(bare) or ID_RE.search(bare):
                issues.append("figure")
                continue
            out.append(sentence.strip())
        kept.append(" ".join(out))
    cleaned = "\n".join(kept)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    return cleaned, issues


def sheet_lines(case, sheets):
    if not sheets:
        return ""
    if len(sheets) == 1:
        return "Our proposal: " + describe(case, sheets[0]) + "."
    lines = ["We could agree on any of these packages:"]
    lines += [f"Option {LETTERS[i]}: {describe(case, s)}." for i, s in enumerate(sheets)]
    return "\n".join(lines)


def compose(case, body, claims, sheets, questions):
    """Fill placeholders; append anything the model forgot. Returns (body, refs)."""
    by_id = {c["cid"]: c for c in claims}
    used = []

    def fill(match):
        key = match.group(1)
        if key == "SHEETS":
            return sheet_lines(case, sheets)
        if key == "QUESTIONS":
            return " ".join(q.strip() for q in questions if q.strip())
        cid = key.split(":", 1)[1]
        if cid in by_id and cid not in used and len(used) < MAX_PER_MESSAGE:
            used.append(cid)
            return by_id[cid]["sentence"]
        return ""

    text = PLACEHOLDER.sub(fill, body or "")
    missing = [c["cid"] for c in claims if c["cid"] not in used][: MAX_PER_MESSAGE - len(used)]
    extra = [by_id[cid]["sentence"] for cid in missing]
    used += missing
    if extra:
        text = _insert_before_closing(text, " ".join(extra))
    if sheets and "{{SHEETS}}" not in (body or "") and sheet_lines(case, sheets) not in text:
        text = _insert_before_closing(text, sheet_lines(case, sheets))
    if questions and "{{QUESTIONS}}" not in (body or ""):
        q = " ".join(x.strip() for x in questions if x.strip() and x.strip() not in text)
        if q:
            text = _insert_before_closing(text, q)
    refs = []
    for cid in used:
        refs += [i for i in by_id[cid]["ids"] if i not in refs]
    return re.sub(r"\n{3,}", "\n\n", text).strip()[:BODY_LIMIT], refs[:20]


def _insert_before_closing(text, block):
    lines = text.rstrip().splitlines()
    for i in range(len(lines) - 1, max(-1, len(lines) - 4), -1):
        if re.match(r"\s*(best regards|kind regards|regards|sincerely|thank you|many thanks)", lines[i], re.I):
            return "\n".join(lines[:i] + ["", block, ""] + lines[i:])
    return (text.rstrip() + "\n\n" + block).strip()


SIGNATURE = "Best regards\nHollerau Pumpenwerke GmbH, Purchasing"


def template(case, tone, tactic, has_sheets, ask_breakdown, first):
    """A deterministic body with placeholders, used without a model or when its text is unusable."""
    greet = "Dear colleagues,"
    if first:
        opener = {
            "warm": "thank you for your quote and for the good cooperation over the years.",
            "firm": "thank you for your quote. We have reviewed it carefully and cannot accept it as it stands.",
        }.get(tone, "thank you for your quote, which we have reviewed carefully.")
    else:
        opener = {
            "warm": "thank you for your reply - we appreciate the step you made.",
            "firm": "thank you for your reply. We are not there yet.",
        }.get(tone, "thank you for your reply.")
    middle = {
        "trade": "We have put together packages that give you more of what matters to you in exchange for a better price.",
        "hold": "We have looked again at our position and would ask you to reconsider yours.",
        "close_push": "We are close. One more step from your side and we can sign.",
        "probe": "To find a fair solution for both sides we would like to understand your costs better.",
    }.get(tactic, "We would like to reach an agreement on the following basis.")
    parts = [greet, opener, middle, "{{CLAIM_BLOCK}}"]
    if has_sheets:
        parts.append("{{SHEETS}}")
    if ask_breakdown:
        parts.append("Could you send us a cost breakdown for this part?")
    parts.append("{{QUESTIONS}}")
    parts.append(SIGNATURE)
    return "\n".join(parts)


def finish_template(body, claims):
    claim_marks = " ".join(f"{{{{CLAIM:{c['cid']}}}}}" for c in claims[:MAX_PER_MESSAGE])
    return body.replace("{{CLAIM_BLOCK}}", claim_marks)


def subject(case, threads_subject=None):
    base = threads_subject or case.get("title") or "Your quote"
    base = re.sub(r"^(re:\s*)+", "", base, flags=re.I)
    return ("Re: " + base)[:SUBJECT_LIMIT]

