"""Model access through the harness gateway (`services.complete`), as a LangChain chat model.

The gateway is text-in/text-out (no tools, no response_format), synchronous and not thread-safe, so
calls are serial, never retried, and JSON is parsed here.
"""

import json
import re

try:  # LangChain is optional at runtime: without it we call the gateway directly.
    from langchain_core.language_models.chat_models import BaseChatModel
    from langchain_core.messages import AIMessage, BaseMessage
    from langchain_core.outputs import ChatGeneration, ChatResult
except Exception:  # pragma: no cover - exercised by the import-fallback test
    BaseChatModel = None

ROLES = {"system": "system", "human": "user", "ai": "assistant"}


def to_dicts(messages):
    out = []
    for m in messages:
        if isinstance(m, dict):
            out.append({"role": m["role"], "content": m["content"]})
        else:
            out.append({"role": ROLES.get(m.type, "user"), "content": m.content})
    return out


if BaseChatModel is not None:

    class ServicesChatModel(BaseChatModel):
        """LangChain chat model whose every call goes through the harness's budgeted gateway."""

        complete: object  # services.complete

        @property
        def _llm_type(self):
            return "arena-harness-gateway"

        def _generate(self, messages: list[BaseMessage], stop=None, run_manager=None, **kwargs):
            text = self.complete(to_dicts(messages))
            return ChatResult(generations=[ChatGeneration(message=AIMessage(content=text or ""))])

else:
    ServicesChatModel = None


class Gateway:
    """One object per decide: counts calls and failures, never raises."""

    def __init__(self, services):
        self.services = services
        self.calls = 0
        self.failures = 0
        self.model = None
        if ServicesChatModel is not None and services is not None:
            try:
                self.model = ServicesChatModel(complete=services.complete)
            except Exception:
                self.model = None

    def text(self, messages):
        self.calls += 1
        try:
            if self.model is not None:
                out = self.model.invoke(messages).content
            else:
                out = self.services.complete(to_dicts(messages))
            if not isinstance(out, str) or not out.strip():
                raise ValueError("empty model reply")
            return out
        except Exception:
            self.failures += 1
            return None

    def json(self, messages):
        out = parse_json(self.text(messages))
        if out is None and self.calls > self.failures:
            self.failures += 1
        return out


FENCE = re.compile(r"```(?:json)?\s*(.*?)```", re.S)


def parse_json(text):
    """The first JSON object in a model reply, or None."""
    if not text:
        return None
    m = FENCE.search(text)
    if m:
        text = m.group(1)
    start = text.find("{")
    while start >= 0:
        depth, in_str, esc = 0, False, False
        for i in range(start, len(text)):
            ch = text[i]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
            elif ch == '"':
                in_str = True
            elif ch == "{":
                depth += 1
            elif ch == "}":
                depth -= 1
                if depth == 0:
                    try:
                        value = json.loads(text[start : i + 1])
                        return value if isinstance(value, dict) else None
                    except ValueError:
                        break
        start = text.find("{", start + 1)
    return None

"""Find the harness run this case belongs to, and open its journal read-only.

The engine journals every case (with a hash of its definition) before the agent prepares it, so the
newest unfinished run that holds this case with the same hash is ours. Nothing here ever writes.
"""

import json
import sqlite3
from pathlib import Path

from arena_kit.harness.state import digest

ROOT = Path(__file__).resolve().parents[3]  # starter-kit/
DEFAULT_RUNS = ROOT.parent / ".runs"
MAX_SCAN = 30


def stable_hash(case):
    return digest({k: v for k, v in case.items() if k not in ("open", "seconds_left")})


def connect(run_dir):
    con = sqlite3.connect(f"file:{Path(run_dir) / 'run.sqlite'}?mode=ro", uri=True, timeout=1.0)
    con.execute("PRAGMA query_only = ON")
    return con


def _mtime(path):
    times = [p.stat().st_mtime for p in (path / "run.sqlite", path / "run.sqlite-wal") if p.exists()]
    return max(times, default=0.0)


def find(case, runs_dir=None):
    """The run directory of this case's harness run, or None."""
    base = Path(runs_dir) if runs_dir else DEFAULT_RUNS
    try:
        dirs = [p for p in base.iterdir() if (p / "run.sqlite").is_file()]
    except OSError:
        return None
    want = stable_hash(case)
    for run in sorted(dirs, key=_mtime, reverse=True)[:MAX_SCAN]:
        try:
            con = connect(run)
            try:
                row = con.execute("SELECT value FROM cases WHERE id=?", (case["case_id"],)).fetchone()
                status = con.execute("SELECT value FROM meta WHERE key='status'").fetchone()
            finally:
                con.close()
        except sqlite3.Error:
            continue
        if not row or json.loads(row[0]).get("case_hash") != want:
            continue
        if status and json.loads(status[0]) == "completed":
            continue
        return run
    return None

