"""Episode Extractor: the finished cases of this run, read from its journal (read-only).

An episode joins what the harness recorded (result, score, cost breakdown, supplier reasons, every
supplier reply) with what our agent recorded in its own state (tactics, predictions, lessons used,
its closing reflection).
"""

import json
from urllib.parse import unquote

from .runlocate import connect

REASONS = 12


def signature(run_dir):
    """Cheap fingerprint of which cases have finished - re-extract only when it changes."""
    con = connect(run_dir)
    try:
        rows = con.execute(
            "SELECT id, json_extract(value, '$.result') IS NOT NULL, "
            "coalesce(json_extract(value, '$.agent_state.closed'), 0) FROM cases ORDER BY id"
        ).fetchall()
    finally:
        con.close()
    return tuple((r[0], bool(r[1]), bool(r[2])) for r in rows if r[1] or r[2])


def _replies(con, session_id):
    """Supplier replies to our messages, per supplier, in order: [{status, price, claims}]."""
    out = {}
    if not session_id:
        return out
    prefix = f"sessions/{session_id}/threads/"
    rows = con.execute(
        "SELECT path, body, response FROM operations WHERE status='done' AND path LIKE ? ORDER BY created",
        (f"sessions/%/threads/%/messages",),
    ).fetchall()
    for path, body, response in rows:
        path = unquote(path)
        if not path.startswith(prefix):
            continue
        sid = path[len(prefix) : -len("/messages")]
        try:
            reply = json.loads(response or "{}")
            sent = json.loads(body or "{}").get("message") or {}
        except ValueError:
            continue
        if sent.get("action"):
            continue
        sheets = reply.get("term_sheets") or [{}]
        out.setdefault(sid, []).append(
            {
                "status": reply.get("status") or ("ended" if reply.get("ended") or "result" in reply else None),
                "price": (sheets[0].get("terms") or {}).get("unit_price"),
                "claims": [r.get("result") for r in reply.get("claim_results") or []],
                "refs": sent.get("refs") or [],
                "our_prices": [(s.get("terms") or {}).get("unit_price") for s in sent.get("term_sheets") or []],
            }
        )
    return out


def extract(run_dir, exclude=None):
    """[episode] for every case of the run that has ended or that our agent has closed."""
    con = connect(run_dir)
    try:
        rows = con.execute("SELECT id, value FROM cases ORDER BY id").fetchall()
        episodes = []
        for cid, value in rows:
            if cid == exclude:
                continue
            try:
                rec = json.loads(value)
            except ValueError:
                continue
            st = rec.get("agent_state") or {}
            result = rec.get("result")
            if not result and not st.get("closed"):
                continue
            case = rec.get("case") or {}
            sups = st.get("sup") or {}
            trace = (result or {}).get("trace") or []
            episodes.append(
                {
                    "case_id": cid,
                    "type": case.get("type"),
                    "goal": (case.get("buyer") or {}).get("category_goal"),
                    "has_alternative": ((case.get("buyer") or {}).get("alternative") or {}).get("kind")
                    not in (None, "none"),
                    "suppliers": {
                        s: {"tags": (sups.get(s) or {}).get("tags") or []} for s in case.get("suppliers") or []
                    },
                    "result": {
                        k: (result or {}).get(k)
                        for k in ("deal", "supplier_id", "score", "c_open", "c_deal", "c_best", "c_alt",
                                  "must_haves_ok", "cost_breakdown")
                    }
                    if result
                    else None,
                    "end_reason": rec.get("end_reason"),
                    "reasons": [
                        str(t.get("reasons"))[:300] for t in trace if t.get("actor") != "buyer" and t.get("reasons")
                    ][-REASONS:],
                    "replies": _replies(con, rec.get("session_id")),
                    "log": st.get("log") or [],
                    "reflection": st.get("reflection") or {},
                    "close": st.get("close") or {},
                }
            )
        return episodes
    finally:
        con.close()

"""Diagnostician: deterministic lessons from one finished episode.

Each lesson has a scope (global, case_type, goal, archetype, supplier), a polarity (do / avoid), a
lever and a code; codes also drive policy knobs (see `consolidate.knobs`).
"""

WEAK = 0.3  # supplier price move (%) below which we call it "did not move"


def lesson(level, value, polarity, lever, code, text, case_id, weight=1.0):
    return {
        "scope": {"level": level, "value": value or ""},
        "polarity": polarity,
        "lever": lever,
        "code": code,
        "text": text,
        "case": case_id,
        "weight": weight,
    }


def _scopes(ep, sid):
    """Where a supplier-specific observation applies: its archetypes and the supplier itself."""
    tags = (ep["suppliers"].get(sid) or {}).get("tags") or []
    return [("archetype", t) for t in tags] + [("supplier", sid)]


def _kind_of(log, refs):
    """Claim kinds of a message, from our own log (refs -> kinds)."""
    for entry in log:
        if set(entry.get("refs") or []) == set(refs) and entry.get("claim_kinds"):
            return entry["claim_kinds"]
    return []


def diagnose(ep):
    out = []
    cid = ep["case_id"]
    res = ep.get("result") or {}
    for sid, replies in (ep.get("replies") or {}).items():
        statuses = [r.get("status") for r in replies]
        tags = ", ".join((ep["suppliers"].get(sid) or {}).get("tags") or []) or "untagged"
        # Pushed after a final offer and the supplier walked.
        for i, status in enumerate(statuses):
            if status == "walked_away" and i > 0 and statuses[i - 1] == "final_offer":
                for level, value in _scopes(ep, sid) + [("case_type", ep.get("type"))]:
                    out.append(lesson(level, value, "avoid", "closing", "WALKED_AFTER_PUSH",
                                      f"Pushing after a final offer made a supplier ({tags}) walk away; accept a "
                                      "final offer that beats our alternative.", cid))
                break
        # Walked or declined before any final offer: our asks were too aggressive.
        if statuses and statuses[-1] in ("walked_away", "no_bid") and "final_offer" not in statuses:
            for level, value in _scopes(ep, sid):
                out.append(lesson(level, value, "avoid", "price", "WALKED_EARLY",
                                  f"A supplier ({tags}) walked away without a final offer; open closer to its "
                                  "offer and concede in visible steps.", cid))
        # Agreed to our very first ask: we anchored too softly.
        if statuses[:1] == ["agreed"]:
            for level, value in _scopes(ep, sid):
                out.append(lesson(level, value, "do", "price", "TOO_SOFT",
                                  f"A supplier ({tags}) agreed to our first ask at once; anchor lower next time.",
                                  cid))
        # How claims landed.
        for i, r in enumerate(replies):
            kinds = _kind_of(ep.get("log") or [], r.get("refs") or [])
            for j, result in enumerate(r.get("claims") or []):
                kind = kinds[j] if j < len(kinds) else "data"
                if result == "contradicted":
                    out.append(lesson("global", "", "avoid", "claims", f"CONTRADICTED:{kind}",
                                      f"A '{kind}' data claim came back contradicted; do not cite that kind "
                                      "without an exact match.", cid))
            if r.get("claims") and "verified" in r["claims"] and i > 0:
                before, after = replies[i - 1].get("price"), r.get("price")
                if before and after:
                    move = (before - after) / before * 100
                    kind = "/".join(sorted(set(kinds))) or "data"
                    for level, value in _scopes(ep, sid):
                        if move >= 1.0:
                            out.append(lesson(level, value, "do", "claims", f"CLAIM_MOVED:{kind}",
                                              f"Verified {kind} arguments moved a supplier ({tags}) on price.", cid,
                                              0.7))
                        elif move < WEAK:
                            out.append(lesson(level, value, "avoid", "claims", f"CLAIM_IGNORED:{kind}",
                                              f"Verified {kind} arguments did not move a supplier ({tags}); "
                                              "trade on other levers instead.", cid, 0.7))
        # When it reached its final offer: our concession horizon.
        if "final_offer" in statuses:
            r = statuses.index("final_offer") + 1
            for level, value in _scopes(ep, sid):
                out.append(lesson(level, value, "do", "timing", f"FINAL_AT:{r}",
                                  f"A supplier ({tags}) gave its final offer after {r} of our messages; plan "
                                  "concessions to land by then.", cid, 0.5))
    # Outcome-level lessons from the harness result (exact score and cost breakdown).
    if res.get("score") is not None:
        breakdown = res.get("cost_breakdown") or {}
        if res.get("deal") and res["score"] < 0.4:
            worst = sorted(
                ((k, v) for k, v in breakdown.items() if k not in ("price",) and (v or 0) > 0),
                key=lambda kv: -kv[1],
            )[:1]
            for k, v in worst:
                out.append(lesson("global", "", "do", k, f"LEFT:{k}",
                                  f"A weak deal (score {res['score']:.2f}) still paid EUR {v:,.0f} on {k}; "
                                  f"negotiate {k.replace('_', ' ')} explicitly.", cid, 0.6))
        if not res.get("deal") and not ep.get("has_alternative"):
            out.append(lesson("global", "", "avoid", "closing", "NO_DEAL_NO_ALT",
                              "A case without an alternative ended with no deal (score 0); always close on the best "
                              "acceptable offer.", cid))
    return out

"""Consolidator + Retriever: merge the run's lessons, score them, and pick what applies to a case.

Recursive within a run: a closing reflection reports whether the lessons it used held, and the
case's score confirms or contradicts them, so later cases see lessons weighted by outcomes.
"""

import hashlib
import math

from .diagnose import diagnose

SPECIFICITY = {"supplier": 4.0, "archetype": 3.0, "case_type": 2.0, "goal": 2.0, "global": 1.0}
CAP_PER_SCOPE = 6


def key_of(lesson):
    s = lesson["scope"]
    tail = lesson.get("code") or hashlib.sha1(lesson["text"].lower().encode()).hexdigest()[:8]
    return f"{s['level']}|{s['value']}|{lesson['lever']}|{lesson['polarity']}|{tail}"


def merge(episodes):
    """{key: lesson with support/contradict/cases} from every episode of the run."""
    merged = {}

    def add(item, weight=1.0):
        k = key_of(item)
        cur = merged.get(k)
        if cur is None:
            cur = merged[k] = {**item, "key": k, "support": 0.0, "contradict": 0.0, "cases": []}
        cur["support"] += weight
        cur["text"] = item["text"]  # latest wording wins
        if item.get("case") and item["case"] not in cur["cases"]:
            cur["cases"].append(item["case"])

    feedback = []
    for ep in episodes:
        for item in diagnose(ep):
            add(item, item.get("weight", 1.0))
        refl = ep.get("reflection") or {}
        for item in refl.get("lessons") or []:
            if isinstance(item, dict) and item.get("text") and isinstance(item.get("scope"), dict):
                add({**item, "case": ep["case_id"]}, 1.0)
        # lessons the case used: held / failed by its reflection, else by its score
        used = {k for entry in ep.get("log") or [] for k in entry.get("lessons") or []}
        verdicts = refl.get("feedback") or {}
        score = (ep.get("result") or {}).get("score")
        for k in used:
            v = verdicts.get(k)
            if v == "held" or (v is None and score is not None and score >= 0.7):
                feedback.append((k, "support", 1.0 if v else 0.5))
            elif v == "failed" or (v is None and score is not None and score < 0.3):
                feedback.append((k, "contradict", 1.0 if v else 0.5))
    for k, field, weight in feedback:
        if k in merged:
            merged[k][field] += weight
    # opposite advice on the same scope and lever contradicts each other
    by_slot = {}
    for item in merged.values():
        slot = (item["scope"]["level"], item["scope"]["value"], item["lever"], item.get("code", "").split(":")[0])
        by_slot.setdefault(slot, []).append(item)
    for items in by_slot.values():
        for a in items:
            a["contradict"] += sum(b["support"] for b in items if b["polarity"] != a["polarity"]) * 0.5
    for item in merged.values():
        item["confidence"] = round(item["support"] / (item["support"] + item["contradict"] + 1e-9), 2)
        item["status"] = "retired" if item["contradict"] > item["support"] else "active"
    return merged


def retrieve(merged, case, tags_by_supplier, k=10):
    """Active lessons that apply to this case, most specific and best supported first."""
    tags = {t for ts in tags_by_supplier.values() for t in ts}
    sups = set(tags_by_supplier)
    goal = (case.get("buyer") or {}).get("category_goal")
    scored = []
    for item in merged.values():
        if item["status"] != "active":
            continue
        level, value = item["scope"]["level"], item["scope"]["value"]
        match = (
            level == "global"
            or (level == "archetype" and value in tags)
            or (level == "supplier" and value in sups)
            or (level == "case_type" and value == case.get("type"))
            or (level == "goal" and value == goal)
        )
        if match:
            score = SPECIFICITY.get(level, 1.0) * item["confidence"] * math.log1p(item["support"])
            scored.append((score, item))
    scored.sort(key=lambda x: -x[0])
    out, per_scope = [], {}
    for _, item in scored:
        slot = (item["scope"]["level"], item["scope"]["value"])
        if per_scope.get(slot, 0) >= CAP_PER_SCOPE:
            continue
        per_scope[slot] = per_scope.get(slot, 0) + 1
        out.append(item)
        if len(out) >= k:
            break
    return out


def knobs(lessons, tags_by_supplier):
    """Policy parameters the deterministic code applies (so learning works without the model too)."""
    out = {"allow_final_push": True, "drop_mult": {}, "blocked_claims": [], "horizon": {}, "tone": {}}
    for sid, tags in tags_by_supplier.items():
        scopes = {("supplier", sid)} | {("archetype", t) for t in tags}
        mult, horizon = 1.0, None
        for item in lessons:
            slot = (item["scope"]["level"], item["scope"]["value"])
            code = item.get("code") or ""
            if slot not in scopes and item["scope"]["level"] != "global":
                continue
            if code == "WALKED_AFTER_PUSH":
                out["allow_final_push"] = False
            elif code == "WALKED_EARLY":
                mult *= 0.75
            elif code == "TOO_SOFT":
                mult *= 1.25
            elif code.startswith("FINAL_AT:"):
                r = int(code.split(":")[1])
                horizon = r if horizon is None else min(horizon, r)
            elif code.startswith("CLAIM_IGNORED:") and slot in scopes:
                out.setdefault("weak_claims", {}).setdefault(sid, []).extend(code.split(":", 1)[1].split("/"))
        out["drop_mult"][sid] = round(max(0.5, min(2.0, mult)), 3)
        if horizon:
            out["horizon"][sid] = max(2, horizon)
    for item in lessons:
        code = item.get("code") or ""
        if code.startswith("CONTRADICTED:"):
            out["blocked_claims"].append(code.split(":", 1)[1])
    out["blocked_claims"] = sorted(set(out["blocked_claims"]))
    return out


def view(episodes, case, tags_by_supplier, k=10):
    merged = merge(episodes)
    lessons = retrieve(merged, case, tags_by_supplier, k)
    return {
        "episodes": len(episodes),
        "lessons": [
            {
                "key": x["key"],
                "scope": x["scope"],
                "polarity": x["polarity"],
                "lever": x["lever"],
                "text": x["text"],
                "confidence": x["confidence"],
                "support": round(x["support"], 2),
                "cases": x["cases"][:5],
            }
            for x in lessons
        ],
        "knobs": knobs(lessons, tags_by_supplier),
    }

