  { key: 'llm', prompt: `${CONTEXT}\n\nDIMENSION: LLM integration & e-mail safety. Check llm.py (ServicesChatModel pydantic field, Gateway failure accounting, parse_json), prompts.py (schema text vs clean_choice/clean_lessons parsing, prompt size limits <=128 KiB request, _fit trimming), graph.py negotiator/strategist/writer nodes (choices for every supplier, two-call path, fails counter), writer.py (lint drops sentences with figures/leaks but keeps placeholders; compose fills placeholders, refs order matches claim sentences, no stray IDs in body that the arena would check, body length), and LangGraph usage (StateGraph with TypedDict, conditional edges, recursion limit, state mutation semantics, any chance LangGraph copies/merges state so mutations to ctx['state'] are lost). Also check that model output can never inject figures/IDs/term sheets outside the menu.` },
]

const FINDINGS = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          file: { type: 'string' },
          line: { type: 'integer' },
          severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
          scenario: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['title', 'file', 'severity', 'scenario', 'fix'],
      },
    },
  },
  required: ['findings'],
}

const VERDICT = {
  type: 'object',
  properties: {
    real: { type: 'boolean' },
    reason: { type: 'string' },
    fix: { type: 'string' },
  },
  required: ['real', 'reason'],
}

const results = await pipeline(
  DIMENSIONS,
  d => agent(d.prompt, { label: `review:${d.key}`, phase: 'Review', schema: FINDINGS }),
  (review, d) => parallel((review?.findings || []).map(f => () =>
    agent(`${CONTEXT}\n\nAdversarially VERIFY this claimed defect in the learner agent. Read the code, and if possible reproduce it with a scratch script (do not edit repo files). Default to real=false if you cannot confirm a concrete failing scenario or if the behaviour is intended/harmless.\n\nClaim: ${f.title}\nFile: ${f.file}:${f.line || ''}\nSeverity claimed: ${f.severity}\nScenario: ${f.scenario}\nProposed fix: ${f.fix}`,
      { label: `verify:${d.key}:${(f.title || '').slice(0, 40)}`, phase: 'Verify', schema: VERDICT })
      .then(v => ({ ...f, dimension: d.key, verdict: v }))
  ))
)

const all = results.flat().filter(Boolean)
const confirmed = all.filter(f => f.verdict && f.verdict.real)
log(`${all.length} findings, ${confirmed.length} confirmed`)
return { confirmed, rejected: all.filter(f => !(f.verdict && f.verdict.real)).map(f => ({ title: f.title, why: f.verdict && f.verdict.reason })) }

